using UnityEngine;using UnityEditor;using System.Linq;
public static class FinalCemeteryCheck{public static string Run(){var m=Resources.Load<Material>("GothicArchitecture/CemeteryEarth");m.SetColor("_BaseColor",new Color(.65f,.58f,.48f));EditorUtility.SetDirty(m);AssetDatabase.SaveAssets();var g=PrefabUtility.LoadPrefabContents("Assets/Resources/ExpeditionEnemies/MuckResidents/Golem funerario.prefab");try{var c=g.GetComponent<CapsuleCollider>();if(Mathf.Abs(c.height-2.2f)>.01f)throw new System.Exception("Golem size");return "PASS Golem capsule 2.2m; cemetery earth adjusted";}finally{PrefabUtility.UnloadPrefabContents(g);}}}
